lemma tailK32_rat_antitone_T {T₁ T₂ : ℝ}
    (hT₁_pos : 0 < T₁) (h_T_le : T₁ ≤ T₂) :
    tailK32_rat T₂ ≤ tailK32_rat T₁

theorem A_roots_real {A B : ℂ → ℂ}
    (D : EntireBiInfiniteStrictInterlacingData A B)
    {z : ℂ} (hz : A z = 0) : z.im = 0

theorem B_roots_real {A B : ℂ → ℂ}
    (D : EntireBiInfiniteStrictInterlacingData A B)
    {z : ℂ} (hz : B z = 0) : z.im = 0

theorem no_common {A B : ℂ → ℂ}
    (D : EntireBiInfiniteStrictInterlacingData A B) (z : ℂ) :
    ¬ (A z = 0 ∧ B z = 0)

theorem A_eval_eq_zero_iff {A B : Polynomial ℝ}
    (D : OrientedStrictInterlacingPolynomialData A B) (x : ℝ) :
    A.eval x = 0 ↔ ∃ i : Fin (D.n + 1), D.a i = x

theorem B_eval_eq_zero_iff {A B : Polynomial ℝ}
    (D : OrientedStrictInterlacingPolynomialData A B) (x : ℝ) :
    B.eval x = 0 ↔ ∃ i : Fin D.n, D.b i = x

theorem a_isRoot {A B : Polynomial ℝ}
    (D : OrientedStrictInterlacingPolynomialData A B) (i : Fin (D.n + 1)) :
    A.eval (D.a i) = 0

theorem a_ne_b {A B : Polynomial ℝ}
    (D : OrientedStrictInterlacingPolynomialData A B)
    (i : Fin (D.n + 1)) (j : Fin D.n) : D.a i ≠ D.b j

theorem b_isRoot {A B : Polynomial ℝ}
    (D : OrientedStrictInterlacingPolynomialData A B) (i : Fin D.n) :
    B.eval (D.b i) = 0

theorem no_common_real_root {A B : Polynomial ℝ}
    (D : OrientedStrictInterlacingPolynomialData A B) (x : ℝ) :
    ¬ (A.eval x = 0 ∧ B.eval x = 0)

theorem left_lt {n : ℕ} {a : Fin (n + 1) → ℝ} {b : Fin n → ℝ}
    (h : StrictlyInterlaces a b) (i : Fin n) :
    a i.castSucc < b i

theorem outer_lt {n : ℕ} {a : Fin (n + 1) → ℝ} {b : Fin n → ℝ}
    (h : StrictlyInterlaces a b) (i : Fin n) :
    a i.castSucc < a i.succ

theorem right_lt {n : ℕ} {a : Fin (n + 1) → ℝ} {b : Fin n → ℝ}
    (h : StrictlyInterlaces a b) (i : Fin n) :
    b i < a i.succ

theorem HadamardProductLocallyUniformLimitData.infinite_differentiableAt
    {ι : Type*} {zeroLoc : ι → ℂ}
    {Hex : HadamardFiniteExhaustion zeroLoc}
    (Hluc : HadamardProductLocallyUniformLimitData zeroLoc Hex)
    {s : ℂ} (hs : s ∈ Hluc.region) :
    DifferentiableAt ℂ (infiniteHadamardProduct zeroLoc) s

theorem HadamardProductLocallyUniformLimitData.infinite_differentiableOn
    {ι : Type*} {zeroLoc : ι → ℂ}
    {Hex : HadamardFiniteExhaustion zeroLoc}
    (Hluc : HadamardProductLocallyUniformLimitData zeroLoc Hex) :
    DifferentiableOn ℂ
      (infiniteHadamardProduct zeroLoc) Hluc.region

lemma norm_sub_ge_half_of_two_norm_le {s ρ : ℂ}
    (hlarge : 2 * ‖s‖ ≤ ‖ρ‖) :
    ‖ρ‖ / 2 ≤ ‖s - ρ‖

theorem EntireXiHadamardFactorization.of_quotientFactorization
    {ι : Type} {HZ : ConcreteEntireXiZeroSystem ι}
    {prefactor : ℂ → ℂ}
    (H : EntireXiHadamardQuotientFactorization HZ prefactor) :
    EntireXiHadamardFactorization HZ prefactor

theorem ConcreteCompletedXiHadamardFactorization.toFactorizationData
    {ι : Type} {HZ : ConcreteCompletedXiZeroSystem ι}
    {prefactor : ℂ → ℂ}
    (H : ConcreteCompletedXiHadamardFactorization HZ prefactor) :
    CompletedXiHadamardFactorizationData HZ.zeroLoc prefactor

theorem derivative {p : Polynomial ℂ}
    (hp : PolynomialHyperbolic p) (hderiv : p.derivative ≠ 0) :
    PolynomialHyperbolic p.derivative

theorem of_C_mul {p : Polynomial ℂ} {c : ℂ}
    (h : PolynomialHyperbolic (Polynomial.C c * p)) :
    PolynomialHyperbolic p
